function topoSort(graph) {
  // Validate input
  if (graph === null || typeof graph !== 'object' || Array.isArray(graph)) {
    throw new TypeError();
  }

  // Collect all nodes and validate
  const nodes = new Set();
  const inDegree = {};
  const adjacencyList = {};

  // First pass: collect all nodes from keys and values
  for (const [key, deps] of Object.entries(graph)) {
    if (!Array.isArray(deps)) {
      throw new TypeError();
    }
    nodes.add(key);
    inDegree[key] = 0;
    adjacencyList[key] = [];
    for (const dep of deps) {
      if (typeof dep !== 'string') {
        throw new TypeError();
      }
      nodes.add(dep);
    }
  }

  // Initialize all nodes
  for (const node of nodes) {
    if (!(node in inDegree)) {
      inDegree[node] = 0;
      adjacencyList[node] = [];
    }
  }

  // Second pass: build adjacency list and compute in-degrees
  for (const [node, deps] of Object.entries(graph)) {
    const seen = new Set();
    for (const dep of deps) {
      if (!seen.has(dep)) {
        adjacencyList[dep].push(node);
        inDegree[node]++;
        seen.add(dep);
      }
    }
  }

  // Topological sort using Kahn's algorithm
  const result = [];
  const queue = [];

  // Find all nodes with in-degree 0
  for (const node of nodes) {
    if (inDegree[node] === 0) {
      queue.push(node);
    }
  }

  // Sort queue to maintain lexicographic order
  queue.sort();

  while (queue.length > 0) {
    // Always take the smallest node
    queue.sort();
    const node = queue.shift();
    result.push(node);

    // Process neighbors
    const neighbors = adjacencyList[node].slice().sort();
    for (const neighbor of neighbors) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        queue.push(neighbor);
      }
    }
  }

  // Check for cycles
  if (result.length !== nodes.size) {
    const error = new Error('Cycle detected');
    error.code = 'CYCLE';
    throw error;
  }

  return result;
}

module.exports = { topoSort };
